def get_client_ip(request: Request) -> str:
    """استخراج IP کلاینت"""
    # بررسی IP واقعی در صورت استفاده از Proxy
    forwarded_for = request.request.headers.get("x-forwarded-for")
    if forwarded_for:
        return forwarded_for.split(",")[0].strip()
    real_ip = request.request.headers.get("x-real-ip")
    if real_ip:
        return real_ip
    return request.request.client.host if request.request.client else "unknown"

