class AbstractColumnConfig:
    _column_data_types = {}  # type: ignore
    def __init__(self, **kwargs):
        for key, value in kwargs.items():
            if value is None:
                continue
            if hasattr(self, key):
                setattr(self, key, value)
            elif hasattr(self, f"_{key}"):
                setattr(self, f"_{key}", value)

