class AddRequestContextMiddleware(BaseHTTPMiddleware):
    async def dispatch(self, request: Request, call_next: RequestResponseEndpoint):
        token_prevues_value = request_ctx_var.set(request)  # Set the context variable
        response = None  # Initialize the response variable
        try:
            response = await call_next(
                request
            )  # Try to get the response from the next middleware
        finally:
            request_ctx_var.reset(token_prevues_value)  # Reset the context variable

