def export_transformer(f: Callable):
    def inner(func):
        @wraps(func)
        def view_method(*args, **kwargs):
            request = get_current_request()
            if request:
                request.state.export_serializer = f
            return func(*args, **kwargs)
        return view_method
    return inner

def round_datetime(dt, level="minute"):
    if level == "second":
        return dt.replace(second=dt.second, microsecond=0)
    elif level == "minute":
        return dt.replace(second=0, microsecond=0)
    else:
        raise ValueError("Invalid rounding level. Choose from 'second' or 'minute'.")
