class AsyncSqlalchemyUnitOfWork(AsyncUnitOfWork):
    def __init__(self, session_maker=async_session_maker) -> None:
        self._session_maker = session_maker
        self.repositories: set = set()
        self.is_entered = False
    async def __aenter__(self) -> AsyncAbstractUnitOfWork:
        if self.is_entered:
            raise Exception("UOW IS ALREADY HAS ACTIVE SESSION")
        self._session = self._session_maker()
        self.is_entered = True

